import 'package:flutter/material.dart';

import '../services/api_service.dart';
import '../theme/app_theme.dart';
import '../widgets/app_widgets.dart';

/// Daily review / insights generated by the backend at the end of each day.
class InsightsScreen extends StatefulWidget {
  const InsightsScreen({super.key});

  @override
  State<InsightsScreen> createState() => _InsightsScreenState();
}

class _InsightsScreenState extends State<InsightsScreen> {
  List<Map<String, dynamic>> _items = [];
  List<Map<String, dynamic>> _weeklies = [];
  bool _loading = true;
  bool _running = false;
  bool _weeklyLoaded = false;
  int _tab = 0;
  String? _error;

  @override
  void initState() {
    super.initState();
    _loadDaily();
  }

  Future<void> _loadDaily() async {
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final items = await ApiService().dailyInsights(days: 7);
      if (!mounted) return;
      setState(() {
        _items = items;
        _loading = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _error = e.toString().replaceFirst('Exception: ', '');
        _loading = false;
      });
    }
  }

  Future<void> _loadWeekly() async {
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final items = await ApiService().weeklyReviews(limit: 8);
      if (!mounted) return;
      setState(() {
        _weeklies = items;
        _weeklyLoaded = true;
        _loading = false;
      });
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _error = e.toString().replaceFirst('Exception: ', '');
        _loading = false;
      });
    }
  }

  Future<void> _refresh() {
    return _tab == 0 ? _loadDaily() : _loadWeekly();
  }

  void _selectTab(int value) {
    if (_tab == value) return;
    setState(() {
      _tab = value;
      _error = null;
    });
    if (value == 1 && !_weeklyLoaded) {
      _loadWeekly();
    }
  }

  Future<void> _generate() async {
    setState(() => _running = true);
    try {
      await ApiService().runDailyInsight();
      await _loadDaily();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('今日回顾已生成')),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('生成失败: ${e.toString().replaceFirst('Exception: ', '')}')),
      );
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  Future<void> _backfill() async {
    setState(() => _running = true);
    try {
      await ApiService().backfillInsights(days: 7);
      await _loadDaily();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('已补齐最近 7 天的回顾')),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('补齐失败: ${e.toString().replaceFirst('Exception: ', '')}')),
      );
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  Future<void> _generateWeekly() async {
    setState(() => _running = true);
    try {
      final weekly = await ApiService().runWeeklyReview();
      if (weekly == null) throw Exception('本周数据不足');
      await _loadWeekly();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('本周回顾已生成')),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('生成失败: ${e.toString().replaceFirst('Exception: ', '')}')),
      );
    } finally {
      if (mounted) setState(() => _running = false);
    }
  }

  Future<void> _toTodo(String text) async {
    try {
      await ApiService().createTodoItem({
        'title': text,
        'status': 'pending',
        'priority': 0,
      });
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('已转为待办')),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('创建待办失败: $e')),
      );
    }
  }

  Future<void> _toSchedule(String text) async {
    final start = DateTime.now().toUtc().add(const Duration(hours: 1));
    final end = start.add(const Duration(hours: 1));
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('转为日程'),
        content: Text('将创建：$text\n\n时间：${_shortTime(start.toLocal())} - ${_shortTime(end.toLocal())}'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('取消'),
          ),
          FilledButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('创建'),
          ),
        ],
      ),
    );
    if (ok != true) return;
    try {
      await ApiService().createScheduleEvent({
        'title': text,
        'start_time': start.toIso8601String(),
        'end_time': end.toIso8601String(),
      });
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('已创建日程')),
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('创建日程失败: $e')),
      );
    }
  }

  String _shortTime(DateTime d) =>
      '${d.month}月${d.day}日 ${d.hour.toString().padLeft(2, '0')}:${d.minute.toString().padLeft(2, '0')}';

  String _dayLabel(String raw) {
    final parsed = DateTime.tryParse(raw);
    if (parsed == null) return raw;
    const weekdays = ['一', '二', '三', '四', '五', '六', '日'];
    final now = DateTime.now();
    final isToday = parsed.year == now.year &&
        parsed.month == now.month &&
        parsed.day == now.day;
    final prefix = isToday ? '今天 · ' : '';
    return '$prefix${parsed.month} 月 ${parsed.day} 日 周${weekdays[parsed.weekday - 1]}';
  }

  String _weekLabel(Map<String, dynamic> week) {
    final period = week['period'];
    if (period is Map) {
      final start = (period['start'] ?? '').toString();
      final end = (period['end'] ?? '').toString();
      if (start.isNotEmpty && end.isNotEmpty) return '$start ~ $end';
    }
    final start = (week['week_start'] ?? '').toString();
    final end = (week['week_end'] ?? '').toString();
    return '$start ~ $end';
  }

  Widget _tabChip(AppPalette palette, int value, String label) {
    final selected = _tab == value;
    return InkWell(
      onTap: () => _selectTab(value),
      borderRadius: BorderRadius.circular(18),
      child: Container(
        alignment: Alignment.center,
        padding: const EdgeInsets.symmetric(horizontal: 13, vertical: 6),
        decoration: BoxDecoration(
          color: selected ? palette.primary : palette.card,
          borderRadius: BorderRadius.circular(18),
          border: Border.all(color: selected ? palette.primary : palette.line),
        ),
        child: Text(
          label,
          style: TextStyle(
            fontSize: 10.5,
            fontWeight: FontWeight.w700,
            color: selected ? Colors.white : palette.muted,
          ),
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final palette = AppPalette.of(context);
    return Scaffold(
      backgroundColor: palette.background,
      body: SafeArea(
        child: Column(
          children: [
            PageHeader(
              kicker: 'Insights',
              title: '回顾',
              subtitle: _tab == 0 ? '近 7 天的每日回顾' : '已保存的每周回顾',
              actions: [
                RoundIconButton(
                  icon: Icons.arrow_back_rounded,
                  onTap: () => Navigator.maybePop(context),
                ),
                if (_tab == 0) ...[
                  const SizedBox(width: 6),
                  RoundIconButton(
                    icon: Icons.calendar_month_outlined,
                    tooltip: '补最近 7 天',
                    onTap: _running ? null : _backfill,
                  ),
                  const SizedBox(width: 6),
                  RoundIconButton(
                    icon: _running ? Icons.hourglass_top_rounded : Icons.auto_awesome,
                    tooltip: '生成今天的回顾',
                    onTap: _running ? null : _generate,
                  ),
                ] else ...[
                  const SizedBox(width: 6),
                  RoundIconButton(
                    icon: _running ? Icons.hourglass_top_rounded : Icons.auto_awesome,
                    tooltip: '生成本周回顾',
                    onTap: _running ? null : _generateWeekly,
                  ),
                ],
              ],
            ),
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: Row(
                children: [
                  _tabChip(palette, 0, '每日回顾'),
                  const SizedBox(width: 6),
                  _tabChip(palette, 1, '每周回顾'),
                ],
              ),
            ),
            const SizedBox(height: 8),
            Expanded(
              child: _loading
                  ? Center(child: CircularProgressIndicator(color: palette.primary))
                  : _error != null
                      ? ListView(
                          physics: const AlwaysScrollableScrollPhysics(),
                          children: [
                            const SizedBox(height: 40),
                            ErrorState(onRetry: _refresh),
                          ],
                        )
                      : _tab == 0
                          ? _buildDaily(palette)
                          : _buildWeekly(palette),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildDaily(AppPalette palette) {
    if (_items.isEmpty) {
      return ListView(
        physics: const AlwaysScrollableScrollPhysics(),
        children: [
          const SizedBox(height: 50),
          EmptyState(
            icon: Icons.insights_outlined,
            title: '还没有每日回顾',
            subtitle: '晚上 22:00 会自动生成，也可以现在生成今天的。',
            action: FilledButton.icon(
              onPressed: _running ? null : _generate,
              icon: const Icon(Icons.auto_awesome, size: 17),
              label: const Text('生成今天的回顾'),
            ),
          ),
        ],
      );
    }
    return RefreshIndicator(
      onRefresh: _loadDaily,
      color: palette.primary,
      child: ListView(
        padding: const EdgeInsets.fromLTRB(16, 4, 16, 24),
        children: [
          for (final item in _items) ...[
            _InsightCard(
              insight: item,
              dayLabel: _dayLabel((item['day'] ?? '').toString()),
              onTodo: _toTodo,
              onSchedule: _toSchedule,
            ),
            const SizedBox(height: 12),
          ],
        ],
      ),
    );
  }

  Widget _buildWeekly(AppPalette palette) {
    if (_weeklies.isEmpty) {
      return ListView(
        physics: const AlwaysScrollableScrollPhysics(),
        children: [
          const SizedBox(height: 50),
          EmptyState(
            icon: Icons.calendar_view_week_outlined,
            title: '还没有每周回顾',
            subtitle: '每周五 18:00 自动生成，也可以现在生成。',
            action: FilledButton.icon(
              onPressed: _running ? null : _generateWeekly,
              icon: const Icon(Icons.auto_awesome, size: 17),
              label: const Text('生成本周回顾'),
            ),
          ),
        ],
      );
    }
    return RefreshIndicator(
      onRefresh: _loadWeekly,
      color: palette.primary,
      child: ListView(
        padding: const EdgeInsets.fromLTRB(16, 4, 16, 24),
        children: [
          for (final week in _weeklies) ...[
            _WeeklyCard(
              week: week,
              periodLabel: _weekLabel(week),
            ),
            const SizedBox(height: 12),
          ],
        ],
      ),
    );
  }
}

class _WeeklyCard extends StatelessWidget {
  const _WeeklyCard({required this.week, required this.periodLabel});

  final Map<String, dynamic> week;
  final String periodLabel;

  @override
  Widget build(BuildContext context) {
    final palette = AppPalette.of(context);
    final summary = (week['summary'] ?? '').toString();
    final wins = _list(week['wins']);
    final inProgress = _list(week['in_progress']);
    final risks = _list(week['risks']);
    final nextWeek = _list(week['next_week']);
    final stats = week['stats'] is Map ? week['stats'] as Map : const {};

    return AppCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(Icons.calendar_view_week_outlined,
                  size: 16, color: palette.primary),
              const SizedBox(width: 6),
              Expanded(
                child: Text(
                  periodLabel,
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w800,
                    color: palette.primary,
                  ),
                ),
              ),
            ],
          ),
          if (summary.isNotEmpty) ...[
            const SizedBox(height: 10),
            Text(
              summary,
              style: TextStyle(fontSize: 13.5, height: 1.7, color: palette.ink),
            ),
          ],
          if (wins.isNotEmpty) _section(palette, '本周成果', wins, palette.success),
          if (inProgress.isNotEmpty) _section(palette, '进行中', inProgress, palette.primary),
          if (risks.isNotEmpty) _section(palette, '风险', risks, palette.accent),
          if (nextWeek.isNotEmpty) _section(palette, '下周重点', nextWeek, palette.primary),
          if (stats.isNotEmpty) ...[
            const SizedBox(height: 12),
            Wrap(
              spacing: 6,
              runSpacing: 6,
              children: [
                _chip(palette, '完成待办', stats['todos_done']),
                _chip(palette, '进行中', stats['todos_pending']),
                _chip(palette, '回顾天数', stats['insight_days']),
              ],
            ),
          ],
        ],
      ),
    );
  }

  List<String> _list(dynamic value) {
    if (value is! List) return const [];
    return value.map((e) => e.toString()).where((e) => e.isNotEmpty).toList();
  }

  Widget _section(AppPalette palette, String title, List<String> lines, Color color) {
    return Padding(
      padding: const EdgeInsets.only(top: 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            title,
            style: TextStyle(
              fontSize: 11,
              fontWeight: FontWeight.w800,
              letterSpacing: 0.4,
              color: color,
            ),
          ),
          const SizedBox(height: 4),
          for (final line in lines)
            Padding(
              padding: const EdgeInsets.only(bottom: 3),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text('· ', style: TextStyle(color: palette.muted)),
                  Expanded(
                    child: Text(
                      line,
                      style: TextStyle(
                          fontSize: 12, height: 1.55, color: palette.ink),
                    ),
                  ),
                ],
              ),
            ),
        ],
      ),
    );
  }

  Widget _chip(AppPalette palette, String label, dynamic value) {
    final count = value is num ? value : int.tryParse('$value') ?? 0;
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: BoxDecoration(
        color: palette.primarySoft,
        borderRadius: BorderRadius.circular(8),
      ),
      child: Text(
        '$label ${count.toInt()}',
        style: TextStyle(fontSize: 10.5, color: palette.primary),
      ),
    );
  }
}

class _InsightCard extends StatelessWidget {
  const _InsightCard({
    required this.insight,
    required this.dayLabel,
    required this.onTodo,
    required this.onSchedule,
  });

  final Map<String, dynamic> insight;
  final String dayLabel;
  final Future<void> Function(String) onTodo;
  final Future<void> Function(String) onSchedule;

  @override
  Widget build(BuildContext context) {
    final palette = AppPalette.of(context);
    final summary = (insight['summary'] ?? '').toString();
    final highlights = _stringList(insight['highlights']);
    final patterns = _stringList(insight['patterns']);
    final suggestions = (insight['suggestions'] as List?) ?? const [];
    final stats = insight['stats'] is Map ? insight['stats'] as Map : const {};

    return AppCard(
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(Icons.insights_outlined, size: 16, color: palette.primary),
              const SizedBox(width: 6),
              Text(
                dayLabel,
                style: TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w800,
                  color: palette.primary,
                ),
              ),
            ],
          ),
          if (summary.isNotEmpty) ...[
            const SizedBox(height: 10),
            Text(
              summary,
              style: TextStyle(
                fontSize: 13.5,
                height: 1.7,
                color: palette.ink,
              ),
            ),
          ],
          if (highlights.isNotEmpty) ...[
            const SizedBox(height: 12),
            _sectionTitle(palette, '完成与发生'),
            for (final line in highlights) _bullet(palette, line),
          ],
          if (patterns.isNotEmpty) ...[
            const SizedBox(height: 12),
            _sectionTitle(palette, '观察'),
            for (final line in patterns) _bullet(palette, line),
          ],
          if (stats.isNotEmpty) ...[
            const SizedBox(height: 12),
            Wrap(
              spacing: 6,
              runSpacing: 6,
              children: [
                for (final entry in _statEntries(stats))
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                    decoration: BoxDecoration(
                      color: palette.primarySoft,
                      borderRadius: BorderRadius.circular(8),
                    ),
                    child: Text(
                      '${entry.$1} ${entry.$2}',
                      style: TextStyle(fontSize: 10.5, color: palette.primary),
                    ),
                  ),
              ],
            ),
          ],
          if (suggestions.isNotEmpty) ...[
            const SizedBox(height: 12),
            _sectionTitle(palette, '建议'),
            for (final raw in suggestions) _suggestion(context, palette, raw),
          ],
        ],
      ),
    );
  }

  Widget _sectionTitle(AppPalette palette, String text) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 4),
      child: Text(
        text,
        style: TextStyle(
          fontSize: 11,
          fontWeight: FontWeight.w800,
          letterSpacing: 0.4,
          color: palette.muted,
        ),
      ),
    );
  }

  Widget _bullet(AppPalette palette, String text) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 3),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text('· ', style: TextStyle(color: palette.muted)),
          Expanded(
            child: Text(
              text,
              style: TextStyle(fontSize: 12, height: 1.55, color: palette.ink),
            ),
          ),
        ],
      ),
    );
  }

  Widget _suggestion(BuildContext context, AppPalette palette, dynamic raw) {
    final map = raw is Map ? raw : <String, dynamic>{'text': raw.toString(), 'action': 'none'};
    final text = (map['text'] ?? '').toString();
    final action = (map['action'] ?? 'none').toString();
    if (text.isEmpty) return const SizedBox.shrink();
    return Container(
      margin: const EdgeInsets.only(top: 6),
      padding: const EdgeInsets.fromLTRB(10, 8, 8, 8),
      decoration: BoxDecoration(
        color: palette.background,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: palette.line),
      ),
      child: Row(
        children: [
          Expanded(
            child: Text(
              text,
              style: TextStyle(fontSize: 12, height: 1.5, color: palette.ink),
            ),
          ),
          if (action == 'todo')
            TextButton(
              onPressed: () => onTodo(text),
              child: const Text('转待办', style: TextStyle(fontSize: 11)),
            )
          else if (action == 'schedule')
            TextButton(
              onPressed: () => onSchedule(text),
              child: const Text('转日程', style: TextStyle(fontSize: 11)),
            ),
        ],
      ),
    );
  }

  List<String> _stringList(dynamic value) {
    if (value is! List) return const [];
    return value.map((e) => e.toString()).where((e) => e.isNotEmpty).toList();
  }

  List<(String, String)> _statEntries(Map stats) {
    final out = <(String, String)>[];
    void add(String key, String label) {
      final v = stats[key];
      if (v is num && v > 0) out.add((label, '$v'));
    }

    add('activity_count', '活动');
    add('chat_message_count', '对话');
    add('todo_done_count', '完成待办');
    add('schedule_count', '日程');
    return out;
  }
}
